-- 145: capacity-limited paged operational snapshots; safe explicit original deletion lifecycle.
-- Requires 144 first. No data migration or bulk deletion is performed by installing this file.
begin;
create function tenant_private.offline_records_authorize(s uuid,d uuid,secret uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
 perform tenant_private.offline_device_require(s,d,secret);
 if tenant_private.member_role(s) is distinct from 'owner' or not coalesce(tenant_private.shared_licensed(s),false) or auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'Owner AAL2 required' using errcode='42501';end if;
 if exists(select 1 from unnest(array['all_catalog_read','all_sales_read','all_purchase_read','all_customer_read','all_debt_read','all_repair_read','all_returns_read','all_order_read','all_warranty_read','all_finance_read','all_supplier_read','all_coupon_read']) a(action) where not coalesce(tenant_private.central_read_permitted(s,a.action),false)) then raise exception 'Export permission denied' using errcode='42501';end if;
end $$;
create function tenant_private.offline_records_manifest(s uuid,d uuid,secret uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
 perform tenant_private.offline_records_authorize(s,d,secret);
 return jsonb_build_object('store',s,'captured_at',now(),'tables',to_jsonb(array['public.mt_accounting_adjustments','public.mt_cash_movements','public.mt_cash_receipts','public.mt_coupons','public.mt_customers','public.mt_debt_payments','public.mt_debts','public.mt_fx_rates','public.mt_indirect_tax_entries','public.mt_installments','public.mt_mixed_sales','public.mt_mixed_tenders','public.mt_online_orders','public.mt_payment_allocations','public.mt_period_closes','public.mt_product_prices','public.mt_products','public.mt_purchase_batches','public.mt_purchases','public.mt_repair_events','public.mt_repair_invoice_lines','public.mt_repair_invoices','public.mt_repair_refunds','public.mt_repairs','public.mt_return_allocations','public.mt_returns','public.mt_sale_lines','public.mt_sales','public.mt_stock_events','public.mt_supplier_payments','public.mt_supplier_returns','public.mt_suppliers','public.mt_warranty_claims','public.mt_warranty_events','public.mt_warranty_parts','tenant_private.bank_accounts','tenant_private.bank_transfers','tenant_private.branch_batches','tenant_private.branch_cash_accounts','tenant_private.branch_cash_attribution','tenant_private.branch_cash_transfers','tenant_private.branch_expense_allocations','tenant_private.branch_fifo_lots','tenant_private.branch_fifo_moves','tenant_private.branch_opening_anchors','tenant_private.branch_opening_checks','tenant_private.branch_purchases','tenant_private.branch_repairs','tenant_private.branch_result_approvals','tenant_private.branch_sales','tenant_private.branch_stock','tenant_private.branch_transfers','tenant_private.branch_vouchers','tenant_private.branches','tenant_private.buyer_price_terms','tenant_private.buyer_product_prices','tenant_private.cash_balances','tenant_private.cost_intakes','tenant_private.cost_postings','tenant_private.customer_profile_edits','tenant_private.guest_orders','tenant_private.local_customer_prices','tenant_private.local_membership_sales','tenant_private.local_membership_terms','tenant_private.marketing_campaigns','tenant_private.membership_directory','tenant_private.membership_rates','tenant_private.opening_debt_equity','tenant_private.order_discounts','tenant_private.order_reservations','tenant_private.pos_loyalty_sales','tenant_private.price_quotes','tenant_private.procurement_requests','tenant_private.product_originals','tenant_private.product_tier_prices','tenant_private.receipt_settings','tenant_private.receipt_snapshots','tenant_private.repair_assignments','tenant_private.repair_estimates','tenant_private.repair_paper_decisions','tenant_private.repair_tasks','tenant_private.return_cost_postings','tenant_private.sale_currencies','tenant_private.sale_invoice_details','tenant_private.sale_warranty_claims','tenant_private.sale_warranty_events','tenant_private.shop_order_confirmations','tenant_private.shop_order_history','tenant_private.shop_order_items','tenant_private.spend_checkout','tenant_private.spend_loyalty_policy','tenant_private.spend_loyalty_sales','tenant_private.spend_pos_redemptions','tenant_private.staff_advance_offsets','tenant_private.staff_advances','tenant_private.staff_payroll','tenant_private.staff_payroll_adjustments','tenant_private.staff_payroll_disbursements','tenant_private.staff_payroll_finalizations','tenant_private.staff_payroll_reversals','tenant_private.staff_shifts','tenant_private.staff_terms','tenant_private.standalone_debt_payments','tenant_private.standalone_debts','tenant_private.standalone_installments','tenant_private.standalone_payment_allocations','tenant_private.stock_consumptions','tenant_private.stock_count_cancellations','tenant_private.stock_count_lines','tenant_private.stock_counts','tenant_private.stock_layers','tenant_private.storefront_products','tenant_private.sy_tax_credit_allocations','tenant_private.sy_tax_credit_events','tenant_private.sy_tax_filing_evidence','tenant_private.sy_tax_input_events','tenant_private.sy_tax_inventory_moves','tenant_private.sy_tax_inventory_parts','tenant_