create function tenant_private.offline_records_page(s uuid,d uuid,secret uuid,relation_name text,after_key jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare query_text text;item record;rows jsonb:='[]';last_key jsonb;total_bytes bigint:=0;row_bytes bigint;done boolean:=true;
begin
 perform tenant_private.offline_records_authorize(s,d,secret);
 if after_key is not null and (jsonb_typeof(after_key) is distinct from 'array' or jsonb_array_length(after_key)>8 or octet_length(after_key::text)>4000) then raise exception 'Invalid cursor' using errcode='22023';end if;
 case relation_name
 when 'public.mt_accounting_adjustments' then query_text:=$fixed$select to_jsonb(r) as record, jsonb_build_array(to_jsonb(r.id)) as key from public.mt_accounting_adjustments r where r.store_id=$1 and ($2 is null or jsonb_build_array(to_jsonb(r.id))>$2) order by jsonb_build_array(to_jsonb(r.id)) limit 25$fixed$;
