 else raise exception 'Unknown operational relation' using errcode='22023';
 end case;
 for item in execute query_text using s,after_key loop
  row_bytes:=octet_length(item.record::text);
  if jsonb_array_length(rows)>0 and total_bytes+row_bytes>1000000 then done:=false;exit;end if;
  rows:=rows||jsonb_build_array(item.record);last_key:=item.key;total_bytes:=total_bytes+row_bytes;
 end loop;
 if jsonb_array_length(rows)=25 then done:=false;end if;
 return jsonb_build_object('store',s,'table',relation_name,'rows',rows,'cursor',last_key,'done',done);
