-- An immutable deletion request is reserved before any Storage API call. It hides the
-- original, prevents re-upload/publication, and records completion only after absence.
create table tenant_private.offline_original_deletions(
 store_id uuid not null,request_id uuid not null,asset_id uuid not null,product_id uuid not null,
 actor uuid not null,device_id uuid not null,payload jsonb not null,
 state text not null default 'reserved' check(state in ('reserved','deleted')),
 created_at timestamptz not null default now(),finished_at timestamptz,
 primary key(store_id,request_id),unique(store_id,asset_id),
 foreign key(store_id,device_id) references tenant_private.offline_devices(store_id,id),
 foreign key(store_id,product_id) references public.mt_products(store_id,id)
);
alter table tenant_private.offline_original_deletions enable row level security;
revoke all on tenant_private.offline_original_deletions from public,anon,authenticated,service_role;

create or replace function tenant_private.product_original_access(p_path text,p_write boolean) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from tenant_private.product_originals m where m.object_path=p_path and tenant_private.member_role(m.store_id)='owner' and (not p_write or (tenant_private.shared_licensed(m.store_id) and not exists(select 1 from tenant_private.offline_original_deletions x where x.store_id=m.store_id and x.asset_id=m.id))))
$$;
create or replace function tenant_private.product_original_reserve(p_store uuid,p_id uuid,p_product uuid,p_alt text) returns jsonb language plpgsql security definer set search_path='' as $$
declare r tenant_private.product_originals%rowtype;
begin
 perform tenant_private.owner_write(p_store);
 if p_id is null or p_alt is null or length(btrim(p_alt)) not between 1 and 100 or not exists(select 1 from public.mt_products where store_id=p_store and id=p_product) then raise exception 'Invalid image' using errcode='22023';end if;
 if exists(select 1 from tenant_private.offline_original_deletions where store_id=p_store and asset_id=p_id) then raise exception 'Image retired' using errcode='22023';end if;
 lock table tenant_private.product_originals in share row exclusive mode;
 select * into r from tenant_private.product_originals where store_id=p_store and id=p_id;
 if found then if r.actor<>auth.uid() or r.product_id<>p_product or r.alt<>btrim(p_alt) then raise exception 'Conflicting image reservation' using errcode='22023';end if;
 else
 if exists(select 1 from tenant_private.design_originals where store_id=p_store and id=p_id) then raise exception 'Image id already used' using errcode='22023';end if;
 if (select count(*) from tenant_private.product_originals)>=500 or (select count(*) from tenant_private.product_originals where store_id=p_store)>=100 or (select count(*) from tenant_private.product_originals where store_id=p_store and product_id=p_product)>=4 then raise exception 'Image quota' using errcode='22023';end if;
 insert into tenant_private.product_originals(store_id,id,product_id,alt,actor) values(p_store,p_id,p_product,btrim(p_alt),auth.uid()) returning * into r;
 end if;
 return jsonb_build_object('id',r.id,'path',r.object_path,'uploaded',exists(select 1 from storage.objects where bucket_id='saas-design-originals' and name=r.object_path));
end $$;
create or replace function tenant_private.product_original_publish(p_store uuid,p_id uuid,p_enabled boolean) returns boolean language plpgsql security definer set search_path='' as $$
declare r tenant_private.product_originals%rowtype;
begin
 perform tenant_private.owner_write(p_store);
 select * into r from tenant_private.product_originals where store_id=p_store and id=p_id;
 if not found or p_enabled is null or exists(select 1 from tenant_private.offline_original_deletions where store_id=p_store and asset_id=p_id) then raise exception 'Invalid or retired asset' using errcode='22023';end if;
 if p_enabled and not exists(select 1 from storage.objects where bucket_id='saas-design-originals' and name=r.object_path) then raise exception 'Upload first' using errcode='22023';end if;
 update tenant_private.product_originals set published=p_enabled where store_id=p_store and id=p_id;return p_enabled;
end $$;
create function tenant_private.offline_original_delete_allowed(p_path text) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from tenant_private.offline_original_deletions x join tenant_private.product_originals m on m.store_id=x.store_id and m.id=x.asset_id join tenant_private.offline_devices d on d.store_id=x.store_id and d.id=x.device_id where m.object_path=p_path and x.state='reserved' and x.actor=auth.uid() and d.actor=auth.uid() and d.state='approved' and auth.jwt()->>'aal'='aal2' and tenant_private.member_role(x.store_id)='owner' and tenant_private.shared_licensed(x.store_id) and not tenant_private.central_action_denied(x.store_id,'product_profile_edit'))
$$;
revoke all on function tenant_private.offline_original_delete_allowed(text) from public,anon,authenticated,service_role;
grant execute on function tenant_private.offline_original_delete_allowed(text) to authenticated;
create policy mt_offline_original_delete on storage.objects for delete to authenticated using(bucket_id='saas-design-originals' and tenant_private.offline_original_delete_allowed(name));

create function tenant_private.offline_original_delete_begin(s uuid,d uuid,secret uuid,op jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare req uuid;asset uuid;pid uuid;original tenant_private.product_originals%rowtype;prior tenant_private.offline_reviewed_requests%rowtype;pending tenant_private.offline_original_deletions%rowtype;uploaded boolean;res jsonb;
begin
 perform tenant_private.owner_write(s);
 perform tenant_private.offline_device_require(s,d,secret);
 if auth.jwt()->>'aal' is distinct from 'aal2' or tenant_private.central_action_denied(s,'product_profile_edit') or not tenant_private.central_read_permitted(s,'all_catalog_read') then raise exception 'Owner AAL2 catalog permission required' using errcode='42501';end if;
 if jsonb_typeof(op) is distinct from 'object' or octet_length(op::text)>4000 or op->>'kind' is distinct from 'originalDelete' or (op->>'store')::uuid is distinct from s or (op->>'confirm')::boolean is distinct from true then raise exception 'Explicit image deletion required' using errcode='22023';end if;
 req:=(op->>'requestId')::uuid;asset:=(op->>'asset')::uuid;pid:=(op->>'product')::uuid;
 if req is null or asset is null or pid is null or op->>'alt' is null or (op->>'published')::boolean is null or (op->>'uploaded')::boolean is null then raise exception 'Invalid image review' using errcode='22023';end if;
 select * into prior from tenant_private.offline_reviewed_requests where store_id=s and request_id=req;
 if found then if prior.actor<>auth.uid() or prior.device_id<>d or prior.payload is distinct from op then raise exception 'Request identity conflict' using errcode='22023';end if;return prior.result;end if;
 select * into pending from tenant_private.offline_original_deletions where store_id=s and request_id=req;
 if found then
  if pending.actor<>auth.uid() or pending.device_id<>d or pending.payload is distinct from op then raise exception 'Request identity conflict' using errcode='22023';end if;
 else
  select * into original from tenant_private.product_originals where store_id=s and id=asset and product_id=pid for update;
  if found then select exists(select 1 from storage.objects where bucket_id='saas-design-originals' and name=original.object_path) into uploaded;end if;
  if original.id is null or original.alt is distinct from op->>'alt' or original.published is distinct from (op->>'published')::boolean or uploaded is distinct from (op->>'uploaded')::boolean or exists(select 1 from tenant_private.offline_original_deletions where store_id=s and asset_id=asset) then
   res:=jsonb_build_object('status','conflict','requestId',req,'current','image_changed');
   insert into tenant_private.offline_reviewed_requests(store_id,request_id,actor,device_id,payload,result) values(s,req,auth.uid(),d,op,res);return res;
  end if;
  insert into tenant_private.offline_original_deletions(store_id,request_id,asset_id,product_id,actor,device_id,payload) values(s,req,asset,pid,auth.uid(),d,op);
  update tenant_private.product_originals set published=false where store_id=s and id=asset;
 end if;
 return jsonb_build_object('status','reserved','requestId',req,'id',asset,'path',s::text||'/'||asset::text||'.jpg','uploaded',exists(select 1 from storage.objects where bucket_id='saas-design-originals' and name=s::text||'/'||asset::text||'.jpg'));
end $$;
create function tenant_private.offline_original_delete_finish(s uuid,d uuid,secret uuid,op jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare res jsonb;req uuid;
begin
 res:=tenant_private.offline_original_delete_begin(s,d,secret,op);
 if res->>'status'<>'reserved' then return res;end if;
 if (res->>'uploaded')::boolean is distinct from false then raise exception 'Storage deletion not confirmed' using errcode='22023';end if;
 req:=(op->>'requestId')::uuid;
 delete from tenant_private.product_originals where store_id=s and id=(op->>'asset')::uuid and product_id=(op->>'product')::uuid;
 update tenant_private.offline_original_deletions set state='deleted',finished_at=now() where store_id=s and request_id=req;
 res:=jsonb_build_object('status','confirmed','requestId',req,'resultId',op->>'asset');
 insert into tenant_private.offline_reviewed_requests(store_id,request_id,actor,device_id,payload,result) values(s,req,auth.uid(),d,op,res);
 return res;
end $$;
create function public.mt_offline_original_delete_begin(s uuid,d uuid,secret uuid,op jsonb) returns jsonb language sql set search_path='' as $$select tenant_private.offline_original_delete_begin(s,d,secret,op)$$;
create function public.mt_offline_original_delete_finish(s uuid,d uuid,secret uuid,op jsonb) returns jsonb language sql set search_path='' as $$select tenant_private.offline_original_delete_finish(s,d,secret,op)$$;
revoke all on function tenant_private.offline_original_delete_begin(uuid,uuid,uuid,jsonb),tenant_private.offline_original_delete_finish(uuid,uuid,uuid,jsonb),public.mt_offline_original_delete_begin(uuid,uuid,uuid,jsonb),public.mt_offline_original_delete_finish(uuid,uuid,uuid,jsonb) from public,anon,authenticated,service_role;
grant execute on function tenant_private.offline_original_delete_begin(uuid,uuid,uuid,jsonb),tenant_private.offline_original_delete_finish(uuid,uuid,uuid,jsonb),public.mt_offline_original_delete_begin(uuid,uuid,uuid,jsonb),public.mt_offline_original_delete_finish(uuid,uuid,uuid,jsonb) to authenticated;
commit;
